def find_connected_components(grid, target=0):
    """Find connected components of target cells"""
    visited = set()
    components = []

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            r2, c2 = stack.pop()
            if (r2, c2) in visited:
                continue
            visited.add((r2, c2))
            stack.extend((r2+dr, c2+dc) for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)] 
                        if 0 <= r2+dr < len(grid) and 0 <= c2+dc < len(grid[0]) 
                        and grid[r2+dr][c2+dc] == target and (r2+dr, c2+dc) not in visited)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == target and (r, c) not in visited:
                comp_visited = set()
                dfs(r, c, comp_visited)
                components.append(comp_visited)

    return components

